package dataTypes_variables_1;

public class dataTypes {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int integer1 = 125, integer2 = 20;
		int integer3 = integer1 + integer2; 
		char character  = 'c';
		boolean integer4 = integer1 < integer2;
		double integer5 = integer1 * integer2;
		
		System.out.println( "The boolean value of integer1 and integer2 = " + integer4 );
		System.out.println("The sum of Two integer " + integer3);
		System.out.println("The character " + character);
		System.out.println("The double value "+integer5);
		
	}

}
